# src/langwatch/prompts/service.py
"""
Facade service for managing LangWatch prompts with guaranteed availability.

This module provides a high-level interface that tries local file loading first,
then falls back to API operations. This ensures prompts work even when offline
or when API is unavailable.

Follows the facade pattern to coordinate between LocalPromptLoader and PromptApiService.
"""
from pathlib import Path
from typing import Any, Dict, List, Literal, Optional
import time
from langwatch.generated.langwatch_rest_api_client.client import (
    Client as LangWatchRestApiClient,
)

from langwatch.utils.initialization import ensure_setup
from langwatch.state import get_instance
from .prompt import Prompt
from .types import FetchPolicy
from .prompt_api_service import PromptApiService
from .local_loader import LocalPromptLoader
from .types import Message, Input, Output, MessageDict, InputDict, OutputDict
from logging import getLogger

logger = getLogger(__name__)


class PromptsFacade:
    """
    Facade service for managing LangWatch prompts with guaranteed availability.

    Provides CRUD operations for prompts with local-first loading and API fallback.
    Coordinates between LocalPromptLoader and PromptApiService to ensure prompts
    work even when offline or when API is unavailable.
    """

    def __init__(
        self,
        rest_api_client: LangWatchRestApiClient,
        prompts_path: Optional[str] = None,
    ):
        """Initialize the prompt service facade with dependencies."""
        self._api_service = PromptApiService(rest_api_client)
        self._local_loader = LocalPromptLoader(
            base_path=Path(prompts_path) if prompts_path else None
        )
        self._cache: Dict[str, Dict[str, Any]] = {}

    @classmethod
    def from_global(cls) -> "PromptsFacade":
        """Create a PromptsFacade instance using the global LangWatch configuration."""
        ensure_setup()
        instance = get_instance()
        if instance is None:
            raise RuntimeError(
                "LangWatch client has not been initialized. Call setup() first."
            )
        return cls(instance.rest_api_client, prompts_path=instance.prompts_path)

    def get(
        self,
        prompt_id: str,
        version_number: Optional[int] = None,
        fetch_policy: Optional[FetchPolicy] = None,
        cache_ttl_minutes: Optional[int] = None,
        tag: Optional[str] = None,
    ) -> Prompt:
        """
        Retrieve a prompt by its ID with configurable fetch policy.

        Args:
            prompt_id: The prompt ID to retrieve
            version_number: Optional specific version number to retrieve
            fetch_policy: How to fetch the prompt. Defaults to MATERIALIZED_FIRST.
            cache_ttl_minutes: Cache TTL in minutes (only used with CACHE_TTL policy). Defaults to 5.
            tag: Optional tag to fetch a specific tagged version (e.g. "production", "staging", or any custom tag).

        Raises:
            ValueError: If both version_number and tag are provided.
            ValueError: If tag is used with MATERIALIZED_ONLY policy.
            ValueError: If the prompt is not found (404 error).
            RuntimeError: If the API call fails for other reasons (auth, server errors, etc.).
        """
        if tag is not None and version_number is not None:
            raise ValueError(
                "Cannot specify both version_number and tag"
            )

        fetch_policy = fetch_policy or FetchPolicy.MATERIALIZED_FIRST

        if tag is not None and fetch_policy == FetchPolicy.MATERIALIZED_ONLY:
            raise ValueError(
                "Tag-based fetch requires API access; incompatible with MATERIALIZED_ONLY policy"
            )

        if fetch_policy == FetchPolicy.MATERIALIZED_ONLY:
            return self._get_materialized_only(prompt_id)
        elif fetch_policy == FetchPolicy.ALWAYS_FETCH:
            return self._get_always_fetch(prompt_id, version_number, tag)
        elif fetch_policy == FetchPolicy.CACHE_TTL:
            return self._get_cache_ttl(
                prompt_id, version_number, cache_ttl_minutes or 5, tag
            )
        else:  # MATERIALIZED_FIRST (default)
            return self._get_materialized_first(prompt_id, version_number, tag)

    def _get_materialized_first(
        self,
        prompt_id: str,
        version_number: Optional[int] = None,
        tag: Optional[str] = None,
    ) -> Prompt:
        """Get prompt using MATERIALIZED_FIRST policy (local first, API fallback).

        When a tag is provided, skips local loading and fetches directly from API
        since tags require API access to resolve.
        """
        # When tag is provided, skip local and go straight to API
        if tag is None:
            local_data = self._local_loader.load_prompt(prompt_id)
            if local_data is not None:
                return Prompt(local_data)

        # Fall back to API if not found locally (or tag was provided)
        api_data = self._api_service.get(prompt_id, version_number, tag=tag)
        return Prompt(api_data)

    def _get_materialized_only(self, prompt_id: str) -> Prompt:
        """Get prompt using MATERIALIZED_ONLY policy (local only, no API calls)."""
        local_data = self._local_loader.load_prompt(prompt_id)
        if local_data is not None:
            return Prompt(local_data)

        raise ValueError(f"Prompt '{prompt_id}' not found in materialized files")

    def _get_always_fetch(
        self,
        prompt_id: str,
        version_number: Optional[int] = None,
        tag: Optional[str] = None,
    ) -> Prompt:
        """Get prompt using ALWAYS_FETCH policy (API first, local fallback)."""
        try:
            api_data = self._api_service.get(prompt_id, version_number, tag=tag)
            return Prompt(api_data)
        except Exception:
            # Fall back to local if API fails
            local_data = self._local_loader.load_prompt(prompt_id)

from typing import List, Any, Dict, Union, Optional, cast, TYPE_CHECKING

from pydantic import BaseModel, ConfigDict, Field, PrivateAttr, computed_field

if TYPE_CHECKING:
    from openai.types.chat import ChatCompletionMessageParam

from liquid import Environment, StrictUndefined, Undefined
from liquid.exceptions import UndefinedError
from .decorators.prompt_tracing import prompt_tracing
from .types import PromptData, Message


class PromptCompilationError(Exception):
    """Error class for template compilation issues"""

    def __init__(
        self, message: str, template: str, original_error: Optional[Exception] = None
    ):
        super().__init__(message)
        self.template = template
        self.original_error = original_error
        self.name = "PromptCompilationError"


# Type for template variables - supporting common data types
TemplateVariables = Dict[
    str, Union[str, int, float, bool, Dict[str, Any], List[Any], None]
]


class Prompt(PromptData):
    """
    A class representing a prompt configuration that can be used with OpenAI's API.
    Handles formatting messages with variables using Liquid templating.
    """

    _raw_data: Optional[PromptData] = PrivateAttr(default=None)

    def __init__(
        self,
        data: Union["PromptData", Dict[str, Any], None] = None,
        **kwargs: Any,
    ):
        if data is not None:
            if isinstance(data, BaseModel):
                init_kwargs = data.model_dump()
            elif isinstance(data, dict):
                init_kwargs = dict(data)
            else:
                init_kwargs = {}
            init_kwargs.update(kwargs)
            super().__init__(**init_kwargs)
            if isinstance(data, PromptData):
                self._raw_data = data.model_copy()
            else:
                self._raw_data = PromptData(**init_kwargs)
        else:
            super().__init__(**kwargs)
            self._raw_data = PromptData(**kwargs)

        # Set prompt default only if not provided (like TypeScript)
        if self.prompt is None:
            self.prompt = self._extract_system_prompt()

    @property
    def raw(self) -> PromptData:
        """Get the raw prompt data"""
        if self._raw_data is not None:
            return self._raw_data
        return PromptData(**self.model_dump())

    def _extract_system_prompt(self) -> str:
        """Extract system prompt from messages, like TypeScript version."""
        if self.messages:
            for message in self.messages:
                if message.role == "system":
                    return message.content
        return ""

    def _compile(self, variables: TemplateVariables, strict: bool) -> "CompiledPrompt":
        """
        Internal method to compile the prompt template with provided variables.
        """
        try:
            # Create environment based on strict mode
            env = Environment(undefined=StrictUndefined if strict else Undefined)

            # Compile main prompt
            compiled_prompt = ""
            if self.prompt:
                template = env.from_string(self.prompt)
                compiled_prompt = template.render(**variables)

            # Compile messages
            compiled_messages: List[Message] = []
            if self.messages:
                for message in self.messages:
                    template = env.from_string(message.content)
                    compiled_content = template.render(**variables)
                    compiled_message = Message(
                        role=message.role,
                        content=compiled_content,
                    )
                    compiled_messages.append(compiled_message)

            # Return simplified CompiledPrompt with variables preserved
            return CompiledPrompt(
                original=self,
                prompt=compiled_prompt,
                compiled_messages=compiled_messages,
                variables=variables.copy(),
            )

        except UndefinedError as error:
            template_str = self.prompt or str(self.messages)
            raise PromptCompilationError(
                f"Failed to compile prompt template: {str(error)}", template_str, error
            )
        except Exception as error:
            template_str = self.prompt or str(self.messages)
            raise PromptCompilationError(
                f"Failed to compile prompt template: {str(error)}", template_str, error
            )

    @prompt_tracing.compile
    def compile(
        self, variables: Optional[TemplateVariables] = None, **kwargs: Any
    ) -> "CompiledPrompt":
        """
        Compile the prompt template with provided variables (lenient - missing variables become empty).

        Args:
            variables: Dictionary containing variable values for template compilation
            **kwargs: Alternative way to pass variables as keyword arguments

        Returns:
            CompiledPrompt instance with compiled content
        """
        if variables is None:
            variables = {}

        # Merge explicit dict with kwargs, kwargs take precedence for conflicts
        merged_variables = {**variables, **kwargs}
        return self._compile(merged_variables, strict=False)

    @prompt_tracing.compile_strict
    def compile_strict(
        self, variables: Optional[TemplateVariables] = None, **kwargs: Any
    ) -> "CompiledPrompt":

    ) -> "CompiledPrompt":
        """
        Compile with validation - throws error if required variables are missing.

        Args:
            variables: Template variables

        Returns:
            CompiledPrompt instance with compiled content

        Raises:
            PromptCompilationError: If required variables are missing or compilation fails
        """
        if variables is None:
            variables = {}

        # Merge explicit dict with kwargs, kwargs take precedence for conflicts
        merged_variables = {**variables, **kwargs}
        return self._compile(merged_variables, strict=True)


class CompiledPrompt(BaseModel):
    """
    Represents a compiled prompt with compiled content and original variables
    """

    model_config = ConfigDict(arbitrary_types_allowed=True)

    original: Prompt = Field(repr=False)
    prompt: str
    compiled_messages: List[Message] = Field(repr=False)
    variables: TemplateVariables

    @computed_field  # type: ignore[prop-decorator]
    @property
    def messages(self) -> List[Dict[str, str]]:
        """
        Returns the compiled messages as a list of dicts compatible with OpenAI's API.
        """
        return [msg.model_dump() for msg in self.compiled_messages]

    def __getattr__(self, name: str) -> Any:
        """Delegate unknown attributes to original prompt for backward compatibility"""
        return getattr(self.original, name)

